verus! {

/// Given three 32‐bit signed integers, returns how many of them are equal.
/// 
/// Ensures:
///   0 ≤ count ≤ 3.
///   count = 3 ↔ all three are equal.
///   count = 2 ↔ exactly two are equal (any pairing).
///   count = 1 ↔ all three are pairwise distinct.
fn count_equal_numbers(a: i32, b: i32, c: i32) -> (count: i32)
    ensures
        0 <= count && count <= 3,
    ensures
        (count == 3) <==> (a == b && b == c),
    ensures
        (count == 2) <==> (
            (a == b && a != c) ||
            (a == c && a != b) ||
            (b == c && a != b)
        ),
    ensures
        (count == 1) <==> (a != b && a != c && b != c),
{
    let res: i32;
    
    if a == b {
        // a and b are equal
        if b == c {
            // a == b == c
            res = 3;
        } else {
            // a == b != c
            res = 2;
        }
    } else {
        // a != b
        if a == c || b == c {
            // exactly one of (a==c) or (b==c) holds
            res = 2;
        } else {
            // no two are equal
            res = 1;
        }
    }

    count = res;

    // discharge the postconditions
    assert(0 <= count && count <= 3);
    assert((count == 3) <==> (a == b && b == c));
    assert((count == 2) <==> (
        (a == b && a != c) ||
        (a == c && a != b) ||
        (b == c && a != b)
    ));
    assert((count == 1) <==> (a != b && a != c && b != c));
}

}

